import{_ as o,o as c,c as d,a3 as t}from"./chunks/framework.DACwFHq9.js";const h=JSON.parse('{"title":"v0.7.0-alpha.1 多余/冗余代码专项审计报告","description":"","frontmatter":{},"headers":[],"relativePath":"Plan/v0.7.0-alpha.1-redundancy-audit-report.md","filePath":"Plan/v0.7.0-alpha.1-redundancy-audit-report.md","lastUpdated":1786186968000}'),r={name:"Plan/v0.7.0-alpha.1-redundancy-audit-report.md"};function s(a,e,l,i,n,u){return c(),d("div",null,[...e[0]||(e[0]=[t('<h1 id="v0-7-0-alpha-1-多余-冗余代码专项审计报告" tabindex="-1">v0.7.0-alpha.1 多余/冗余代码专项审计报告 <a class="header-anchor" href="#v0-7-0-alpha-1-多余-冗余代码专项审计报告" aria-label="Permalink to &quot;v0.7.0-alpha.1 多余/冗余代码专项审计报告&quot;">​</a></h1><blockquote><p>状态：审计完成；2026-08-08 完成独立复查，识别 7 处报告偏差（含 3 处升级为行为 bug、2 处误报测试），待清理执行</p><p>审查日期：2026-08-08</p><p>独立复查日期：2026-08-08</p><p>审查口径：发布计划 <a href="./v0.7.0-alpha.1-release-readiness-and-experience-plan">v0.7.0-alpha.1 发布收口与体验优化记录</a> 第 2.2 节 Alpha 硬门禁——清理 GPT 引入的屎山代码、多余的无用测试和极端边界防护</p><p>审查范围：<code>819db5342ada4c842f464f7f56fd4bf1c0c9254e</code> 之后的 350 个提交、1028 个改动文件（约 143k 插入）；覆盖桌面端 <code>src/</code>、<code>src-tauri/</code> 与移动端 <code>mobile/</code> 的 Recall/Knowledge、移动端资产与聊天存储、LLM 渠道与流式、Sidecar 插件与取消运行时、Guided Flow、工具与工程基础设施、测试基建</p><p>重要说明：本报告为调查结论，<strong>未修改任何文件</strong>；所有发现均经引用搜索核实，不含假阳性。列为&quot;可辩护&quot;的防御性代码未上报。移动端条目仅作版本事实底稿，不纳入桌面端 Alpha 硬门禁。</p></blockquote><h2 id="_1-高优先级-应删-必须清理" tabindex="-1">1. 高优先级（应删 / 必须清理） <a class="header-anchor" href="#_1-高优先级-应删-必须清理" aria-label="Permalink to &quot;1. 高优先级（应删 / 必须清理）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>位置</th><th>类别</th><th>问题</th></tr></thead><tbody><tr><td>1</td><td><code>src/tools/recall/services/api.ts:140-149</code></td><td>恒真分支</td><td><code>resolvePresetId</code> 两个分支返回完全相同（<code>&quot;comprehensive&quot;</code>）；<code>RecallProfile</code> 只有 <code>&quot;semantic&quot;</code> | <code>&quot;associative&quot;</code> 两个成员，死分支恰好覆盖全部取值域，函数等价于 <code>presetId ?? &quot;comprehensive&quot;</code>。<strong>复查定案：删除 <code>profile</code> 形参和死分支，不修映射</strong>（<code>agentMigrationService</code> 已将 profile 作为 deprecated 概念处理；<code>profileDefaults(profile)</code> 仍在使用，删时注意不要顺带删 profile 概念）。</td></tr><tr><td>2</td><td><code>src-tauri/src/commands/sidecar_plugin_manager.rs:377,675-686</code></td><td>死代码</td><td><code>_event_tx</code> 创建后立即丢弃，全文件无任何 <code>send</code>；&quot;事件转发任务&quot; <code>event_rx.recv().await</code> 永不返回、永不发事件。真实事件已在 stdout 循环直接 <code>emit</code>。整个 channel+任务空转，约 13 行可删。</td></tr><tr><td>3</td><td><code>src-tauri/src/commands/llmchat_search.rs:643-728</code></td><td>死代码（旧接口）</td><td><code>search_llm_data</code> 已注册 command（<code>commands.rs:357</code>）但前端零调用（<code>useLlmSearch.ts:250</code> 只走 <code>search_llm_data_stream</code>）。且流式路径（:1088-1214）内联复制了 <code>search_agents</code>/<code>search_sessions</code> 全部逐文件匹配逻辑，两套实现并行。删死命令并让流式复用已有函数。<strong>连带项：<code>src/tools/llm-chat/docs/architecture/search-system.md:3</code> 仍把此 command 列为后端入口且行号锚点 <code>:519</code> 已失效（实际 <code>:644</code>），删命令时需同步修文档。</strong></td></tr><tr><td>4</td><td><code>src-tauri/src/recall/ops.rs:421,480</code></td><td>死代码</td><td><code>delete_entry_files</code>、<code>batch_upsert_entries_logic</code> 全仓库（含测试）无任何调用点，<code>#[allow(dead_code)]</code> 承认无用。<code>io.rs:150 delete_entry</code> 唯一调用方是前者，属死链（合计约 108 行）。</td></tr><tr><td>5</td><td><code>mobile/src/tools/llm-chat/composables/useBranchManager.ts</code></td><td>死代码</td><td>整文件 178 行在 <code>mobile/</code> 内零 import；删除/切换/编辑全走 <code>llmChatStore</code> + <code>useNodeManager</code>（如 <code>LlmChatView.vue:136</code>）。<strong>注：桌面端有两个独立的同名活文件</strong>（<code>src/tools/llm-chat/composables/session/useBranchManager.ts</code>、<code>src/tools/media-generator/composables/useBranchManager.ts</code>），清理时确认路径。此条不纳入桌面端 Alpha 硬门禁。</td></tr><tr><td>6</td><td><code>src/tools/llm-chat/core/context-processors/token-limiter.ts:234-245</code></td><td>死代码</td><td>空体 <code>for</code> 循环，循环体无任何语句，注释自认&quot;逻辑有点绕，直接重算更清晰&quot;，<code>totalSavedTokens</code> 已用 264 行重算。整段 12 行可删。（<strong>复查修正</strong>：原报告称&quot;循环上界恒为 0&quot;有误；实际是三元两个分支都返回 0 导致上界为 <code>i</code>，循环真实执行，但循环体空，结论不变。）</td></tr></tbody></table><h2 id="_2-中优先级-建议清理" tabindex="-1">2. 中优先级（建议清理） <a class="header-anchor" href="#_2-中优先级-建议清理" aria-label="Permalink to &quot;2. 中优先级（建议清理）&quot;">​</a></h2><h3 id="_2-1-recall-knowledge" tabindex="-1">2.1 Recall / Knowledge <a class="header-anchor" href="#_2-1-recall-knowledge" aria-label="Permalink to &quot;2.1 Recall / Knowledge&quot;">​</a></h3><ul><li><strong>复查修正 — 计数和分类</strong>：<code>src-tauri/src/recall/ops.rs</code> / <code>io.rs</code> 实际标注项为 16 个（ops.rs 9 + io.rs 7），不是&quot;约 7 个&quot;。其中 <code>warmup_recall_repository</code>（ops.rs:33）在生产中已被调用（<code>state.rs:96,121</code>、<code>commands/base.rs:35</code>），其 <code>#[allow(dead_code)]</code> 是过时标注而非真实死代码，误删会编译失败，应归入下方&quot;过时标注&quot;条目。真正的测试路径死代码：<code>load_knowledge_base_meta_only</code>、<code>warmup_knowledge_base</code>、<code>load_entries_to_vec</code>、<code>scan_all_vectorized_models</code>、<code>update_recall_models_index</code>（均仅被 <code>migration_baseline.rs</code> 引用），删除需同步裁剪基线测试。<code>delete_entry_files</code> 和 <code>batch_upsert_entries_logic</code> 完全无调用点（已在高优第 4 项）。</li><li><code>recall/ops.rs:32</code>、<code>monitor.rs:27-45</code>、<code>tag_pool.rs:234,369</code>、<code>index/db.rs:48</code>：过时 <code>#[allow(dead_code)]</code> 标注（对应项实际已被生产调用）。复查确认属实；<code>monitor.rs</code> 中 <code>Pending</code> 状态可能是例外（无生产 Rust 调用方），其余均属实。</li><li><code>src-tauri/src/recall/retrieval_pipeline.rs:6</code>：模块级 <code>#![allow(dead_code)]</code> 让约 1900 行失去编译器死代码检测。</li><li><code>src-tauri/src/recall/index/db.rs:44</code>：<code>key_to_id</code> 只写不读（旧 <code>[[Key]]</code> 引用解析残留）。</li><li><code>src-tauri/src/recall/monitor.rs:142-170</code>：<code>ChainPayload</code>/<code>ChainMetadata</code>/<code>RecallMonitorEvent::Chain</code> 从不构造。<strong>复查补充</strong>：前端 TS 有消费者（<code>monitor.ts</code>、<code>RecallLogCard.vue</code>、<code>MessageMonitorPage.vue</code>、<code>FilterPanel.vue</code>），删除须同步清理 TS 侧的 type union、switch case 和 filter label。</li><li><code>src/tools/recall/services/api.ts:386</code> <code>getRetrievalCacheStats</code>、<code>utils/recallUtils.ts:62,86</code> <code>extractTagsFromContent</code>/<code>extractTitleFromContent</code>：无调用点导出。</li><li><strong>⚠️ 复查升级为行为 bug</strong>：<code>src/tools/recall/actions/agentActions.ts:176-177</code>：解构默认值 <code>priority = 100, enabled = true</code>（lines 138-139）使 <code>??</code> fallback 永远不触发，导致 AI agent 调用 <code>upsertEntry</code> 只更新 content 而不传 priority/enabled 时，将已有的自定义值（如 <code>priority: 50, enabled: false</code>）静默重置为默认值。修复：去掉解构默认值，改用 <code>options.priority !== undefined ? options.priority : fullEntry.priority</code> 形式（参考同函数中 <code>tags</code> 字段的正确写法 line 173-175）。</li><li><code>src/tools/recall/core/retrievalPipelineContract.ts</code>（384 行）：纯测试支撑，契约在 Rust/TS/JSON 三处重复维护。<strong>复查修正</strong>：<code>retrievalPipelineMigration.ts</code> 有生产调用方（<code>PlaygroundView.vue:15,103</code> 使用 <code>LEGACY_RETRIEVAL_PRESET_MAP</code>），不属于&quot;纯测试脚手架&quot;，不能整体删除，需单独评估；只有 <code>retrievalPipelineContract.ts</code> 可按此条处理。</li></ul><h3 id="_2-2-移动端" tabindex="-1">2.2 移动端 <a class="header-anchor" href="#_2-2-移动端" aria-label="Permalink to &quot;2.2 移动端&quot;">​</a></h3><ul><li><code>mobile/src/tools/llm-chat/stores/contextPipelineStore.ts</code>：注册/排序/持久化 API 全部无外部调用，仅 <code>executePipeline</code> 被用——空转框架。</li><li><code>mobile/src/tools/asset-manager/services/assetService.ts</code>：约 18 个函数逐字重复 <code>try { invoke } catch { errorHandler.handle(showToUser:false); throw }</code> 样板，且 <code>showToUser:false</code> 下 <code>userMessage</code> 是死参数（<code>chatStorageService.ts:149</code> 已有 <code>invokeStorage</code> 收敛先例）。</li><li><code>mobile/src/tools/asset-manager/services/assetService.ts:267</code> <code>replaceEntityAssetUsages</code>（零调用）、<code>chatStorageService.ts:180-223</code> <code>deleteChatBranch</code>/<code>retryAssetUsageOutbox</code>（仅测试调用）：无生产调用点。</li></ul><h3 id="_2-3-sidecar-llm" tabindex="-1">2.3 Sidecar / LLM <a class="header-anchor" href="#_2-3-sidecar-llm" aria-label="Permalink to &quot;2.3 Sidecar / LLM&quot;">​</a></h3><ul><li><code>src/services/plugin-loader.ts:817-967</code>：<strong>复查修正</strong>：真正的 warning+hardError 双诊断只有 1 处（line 818-840，同一条件同时 push 两个数组）；其余 ~4 处是 <code>hardErrors.push</code> 后紧跟 <code>logger.warn</code>，属单通道冗余记录，不是双诊断。&quot;4+ 处双层记录&quot;的说法夸大了。</li><li><code>packages/llm-core/src/providers/openai-responses.ts:455-464</code>：<code>completed</code> 时&quot;谁长信谁&quot;的长度启发式掩盖 streaming vs 终态语义（仅限 <code>reasoningContent</code>，主 content 已有正确的 terminal-snapshot 优先逻辑）。</li><li><code>src/utils/llm-profile-transfer.ts:243-268</code>：<code>includeSecrets=false</code>（默认）时 <code>collectSensitivePaths</code> 全树遍历结果被完全浪费。</li><li><strong>⚠️ 复查升级为行为 bug</strong>：<code>src/tools/smart-ocr/platform/</code> 三文件实现不一致（<code>plugin-engine.ts:126</code>、<code>extension-registry.ts:27</code>、<code>config-migration.ts:31</code>）有实际行为差异：<code>method: &quot;&quot;</code> 时引擎接受但注册表拒绝，<code>method</code> 字段缺失时仅 <code>config-migration.ts</code> 接受；引擎可接受在选择器里不会出现的贡献点。<code>extension-registry.ts:81-85</code> filter 第一个分支仍是走不到的死逻辑（所有已安装插件都在 <code>pluginStates</code> 里）。</li><li><code>src/composables/useLlmRequest.ts:204-218</code>：Rerank 分支返回硬编码伪造成功，全仓无调用方传 <code>rerankQuery</code>，运行时无法到达——遗留脚手架。</li></ul><h3 id="_2-4-工具-基础设施" tabindex="-1">2.4 工具 / 基础设施 <a class="header-anchor" href="#_2-4-工具-基础设施" aria-label="Permalink to &quot;2.4 工具 / 基础设施&quot;">​</a></h3><ul><li>token-calculator：registry <code>clearCache</code>/<code>getCacheSize</code>（<code>token-calculator.registry.ts:138-146</code>）无调用者的死链；worker <code>listProfiles</code> case（<code>calculator.worker.ts:141</code>）永远不可达；<code>tokenizerRegistryStore.ts</code> <code>engineReady</code>（:132,201,487）从未被读取。</li><li><code>src/tools/rich-text-renderer/composables/useMarkdownAst.ts:57,338-340,446-448</code>：<code>timeoutHandle</code> 从未赋真实值，清理代码操作恒 0；<code>applyPatches</code> 可省一次全树重建。</li><li><code>src/tools/llm-chat/stores/session/sessionRuntimeManager.ts:36</code>：<code>Set.size &gt;= 0</code> 恒真，等价 <code>.has(nodeId)</code>。</li><li><code>src/tools/llm-chat/composables/storage/useChatStorageSeparated.ts</code>：僵尸导出面——<code>flushAll</code>(715)、<code>loadSessions</code>/<code>loadSessionsAll</code>/<code>createDebouncedSave</code>/<code>getSessionsDir</code> 均零调用；<code>saveIndex</code>(380) 无直接外部调用（仅被 <code>saveSessions</code> 内部组合）。<strong>复查修正</strong>：<code>getSessionPath</code> 有真实调用方（<code>SessionsSidebar.vue:192-193</code>），<strong>不在此列</strong>。<code>saveSession</code> 的 <code>_forceWrite</code> 参数（337-339）是死参数但非数据丢失 bug——<code>flushSession</code> 本身已无条件 eager 写，参数是协调器重构后的历史残留，真实写入不受影响。</li><li><code>src/tools/agent-manager/stores/agentStore.ts:410</code> <code>ensureAgentLoaded</code>：标 <code>@deprecated</code> 且零调用。</li></ul><h2 id="_3-冗余-无用测试" tabindex="-1">3. 冗余 / 无用测试 <a class="header-anchor" href="#_3-冗余-无用测试" aria-label="Permalink to &quot;3. 冗余 / 无用测试&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>位置</th><th>问题</th></tr></thead><tbody><tr><td>1</td><td><code>tests/tauri-e2e/specs/recall-runtime-fixture.spec.ts</code></td><td><strong>复查修正：此条为误报，勿删</strong>。三个测试中仅 workspace <code>data-recall-id</code> 等待一步有重叠，设置面板 Profile UI 检查和预向量化 IPC 持久性检查在 vector-workflow spec 里无对应项，删除会丢失真实覆盖。问题是该 spec 未加入任何 preset CI 门禁，应加入而非删除。</td></tr><tr><td>2</td><td><code>tests/tauri-e2e/support/runner-options.test.ts:48-202</code></td><td>10 组断言中 5 组逐条复述 <code>presets.ts</code> 配置表（recall-pipeline、recall-vector、corpus-sample、corpus-full、native），可合并为 1 组；另 5 组测真实解析/合并/覆盖逻辑（recall-curated corpus-mode 提取、recall-chat 去重传播、ollama-vector chat 模型抑制、ollama-chat 双模型构造、private-profile 环境变量读取），须保留。</td></tr><tr><td>3</td><td><code>tests/tauri-e2e/support/recall-curated-corpus.test.ts:140-181</code></td><td><strong>复查修正：此条为误报，勿删</strong>。ZIP 由 <code>createSourceArchive()</code> 在内存中用生成字符串构造，无磁盘 I/O；<code>auditRecallCuratedCorpusArchive</code> 不是一次性迁移工具，而是 <code>recall-curated</code> E2E preset 的存档完整性契约函数，测试的 hash 门禁/条目数/内容泄露防护均为真实不变量。</td></tr><tr><td>4</td><td><code>src-tauri/src/recall/retrieval_pipeline.rs:1406,1414</code> / <code>retrieval_modules.rs:2426</code></td><td>:1406（单臂 key 测试）和 :2426 中 3 条 module ID 复述断言可删。<strong>复查修正：:1414（wire_enums_use_stable_kebab_case_values）须保留</strong>——序列化 <code>PipelineErrorCode</code>/<code>RetrievalPhase</code> 的 kebab-case 字符串是跨 IPC 边界到 TypeScript 的 wire contract，serde 属性被无意修改时前端静默崩溃。:2426 的&quot;无 lens 模块&quot;负向断言和版本常量同步断言也须保留，只删 3 条 ID 复述断言。</td></tr><tr><td>5</td><td><code>src-tauri/src/commands/sidecar_plugin_manager.rs:697-730</code></td><td><code>is_terminal_response</code>、<code>generation_matches</code>、<code>broker_generation_status</code> 三个测试（:697-703, :718-730）复述单行实现，可删。<strong>复查修正：:705-714（<code>broker_result_keeps_forward_identity</code>）须保留</strong>——<code>&quot;forward_result&quot;</code>、<code>&quot;targetId&quot;</code>、<code>&quot;data&quot;</code> 是前端事件监听器消费的 key，是 broker 事件的 IPC wire contract 守卫。</td></tr></tbody></table><p>其余（windows-ui-automation、src/ 与 mobile/ 单测、recall 真实向量 E2E 等）质量合格，未发现应删项。</p><h2 id="_4-低优先级-可选清理" tabindex="-1">4. 低优先级（可选清理） <a class="header-anchor" href="#_4-低优先级-可选清理" aria-label="Permalink to &quot;4. 低优先级（可选清理）&quot;">​</a></h2><ul><li>过时 <code>#[allow(dead_code)]</code>：<code>recall/ops.rs</code>、<code>tag_pool.rs</code>、<code>monitor.rs</code>、<code>index/db.rs</code> 多处</li><li>git-committer：<code>RightSidebar.vue:104</code>/<code>CommitChart.vue:31</code> 未使用的 <code>email</code> 字段；三处显式 <code>persist()</code> 与 <code>deep watch</code> 是否重叠尚需确认 watch 列表是否含 <code>repositories</code> ref；<strong>复查修正：<code>canGenerateMessage</code> 为 2 份拷贝</strong>（<code>PanoramaDashboard.vue:222</code> 和 <code>RepoCard.vue:199</code>），不是 3 份</li><li>dir-search：<code>createSearchId</code> 两份逐字符相同实现（<code>actions.ts:43</code> / <code>useDirSearch.ts:37</code>）；两个独立的 <code>searchIdSequence</code> 计数器在并发下可能产生重复 ID</li><li>vcp-connector：<code>sendUpdateStaticPlaceholders</code> 无调用点；<code>rawBlock</code> 与 <code>args</code> 字段双份手写</li><li>smart-ocr：<code>PluginOcrExtension</code> 死类型别名（<code>extension-registry.ts:25</code>，零 import）；<strong>复查修正：<code>runExclusivePluginJob</code> 的 gate/release 机制不可简化为 <code>await previous.catch()</code></strong>——gate 在 await 之前已注册到 map，防止并发调用竞态，此代码可辩护；abort 处理器&quot;双重赋值&quot;说法不准确，系两个不同来源设置同一标志</li><li><code>src/composables/useFileDrop.ts</code>（<strong>复查修正：路径有误，文件在 <code>src/composables/</code> 而非 <code>src/tools/rich-text-renderer/composables/</code></strong>）：实测 <strong>26</strong> 处（不是&quot;约 20&quot;）无开关控制的 <code>console.log/warn</code></li><li><code>src/tools/llm-chat/docs/architecture/context-post-processing.md</code>：引用了已删除的 <code>core/context-pipeline.ts</code>，文档与代码不同步</li><li><code>src/flows/upgrade</code>：<code>upgradeFlowComposer.ts:39-58</code> 指纹 <code>\\|\\| &quot;none&quot;</code> 兜底；<code>appLifecycleService.ts</code> <code>releaseNotes ?? {}</code> 三连重复（:39, :61, :79）；<strong>复查修正：<code>guidedFlowManager 双 persist</code> 说法不准确</strong>——<code>persist()</code> 和 <code>persistActiveState()</code> 语义不同，各自在合适的时机调用，非冗余双写</li></ul><h2 id="_5-可辩护、未上报-防假阳性说明" tabindex="-1">5. 可辩护、未上报（防假阳性说明） <a class="header-anchor" href="#_5-可辩护、未上报-防假阳性说明" aria-label="Permalink to &quot;5. 可辩护、未上报（防假阳性说明）&quot;">​</a></h2><p>以下代码经核实有真实保护价值，未列入清理清单：</p><ul><li>vcpNodeProtocol 断线双路取消（覆盖无 controller 的 VCPLog 审批，非重复）</li><li>dir-search 多次 <code>signal.aborted</code> 检查（每次检查间有 await，存在真实竞态窗口）</li><li>ElMessageBox 按 <code>action</code> 区分取消/关闭的 try-catch（Element Plus 约定用法，两个分支均可达）</li><li>流式解码 abort 传播的 <code>reader.cancel()</code>（是中止路径本身，不是兜底）</li><li>sessionPersistenceCoordinator / sessionPersistenceRepository 及其测试（真实行为覆盖，非复述）</li></ul><p><strong>复查发现的新问题（原报告未涉及）：</strong></p><ul><li><strong>⚠️ <code>vcpConnectorStore.ts</code> <code>vcpLogWs.onclose</code></strong>：<code>distributedWs.onclose</code> 会调用 <code>abortAllInFlight()</code> + <code>cancelExternalRequests()</code>，但 <code>vcpLogWs.onclose</code>（独立处理 VCPLog socket）缺少 <code>cancelExternalRequests()</code> 调用。VCPLog socket 单独断连时，通过 <code>vcpLogWs</code> 发起的审批请求（有 externalId 但无 inFlightController）将永久挂起。</li><li><code>src/tools/llm-chat/docs/architecture/search-system.md:3</code>：仍把已删除的 <code>search_llm_data</code> command 列为后端入口，且行号锚点 <code>:519</code> 已失效（实际行 <code>:644</code>）——与 <code>context-post-processing.md</code> 同类文档漂移，随高优第 3 项一并修。</li></ul><h2 id="_6-结论与建议顺序" tabindex="-1">6. 结论与建议顺序 <a class="header-anchor" href="#_6-结论与建议顺序" aria-label="Permalink to &quot;6. 结论与建议顺序&quot;">​</a></h2><ul><li><strong>总计</strong>：高 6、中约 25、低约 20（含复查升级的 2 个行为 bug 和 1 个新发现 bug）。</li><li><strong>最优先（桌面 Alpha 门禁）</strong>：高优先级中的五项桌面端条目（H1-H4、H6）合计可直接删约 220 行桌面生产代码（H5 是移动端，不纳入本次门禁）。</li><li><strong>行为 bug 同步修复</strong>：<code>agentActions.ts</code> priority/enabled 覆盖 bug、smart-ocr 三份不一致实现、<code>vcpLogWs.onclose</code> 缺少取消调用，建议与高优先级清理同批次处理。</li><li>建议同步恢复 <code>retrieval_pipeline.rs</code> 等模块的编译器死代码检测（删除模块级 <code>#![allow(dead_code)]</code>）作为长期防线。</li><li><strong>测试方面</strong>：复查发现原报告的 5 个冗余测试条目中有 2 个是误报（recall-runtime-fixture spec 和 recall-curated-corpus test 应保留），有 2 个 wire contract 测试被错误标记为可删（应保留）。实际可安全清理的仅：<code>retrieval_pipeline.rs:1406</code> 的单臂 key 测试、<code>:2426</code> 中 3 条 ID 复述断言、<code>sidecar_plugin_manager.rs</code> 的 3 个恒真单函数测试（:697-703, :718-730），以及 <code>runner-options.test.ts</code> 中 5 个纯配置复述 case。</li></ul><blockquote><p><strong>注</strong>：原报告&quot;Rust 侧 <code>#[allow(dead_code)]</code> 集群可删约 800+ 行&quot;中约 80% 来自 707 行的 <code>migration_baseline.rs</code> 测试文件，生产侧实际约 180 行；原&quot;高优先级六项可直接删约 400 行&quot;含 178 行移动端文件，桌面口径约 220 行。</p></blockquote>',26)])])}const g=o(r,[["render",s]]);export{h as __pageData,g as default};
